static void au0828_irq_callback ( struct urb * urb ) { struct au0828_dmaqueue * dma_q = urb -> context ; struct au0828_dev * dev = container_of ( dma_q , au0828_dev , vidq ) ; unsigned long flags = 0 ; int i ; switch ( urb -> status ) { case 0 : case - ETIMEDOUT : break ; case - ECONNRESET : case - ENOENT : case - ESHUTDOWN : au0828_isocdbg ( "au0828_irq_callback called: status kill\n" ) ; return ; default : au0828_isocdbg ( "urb completion error %d.\n" , urb -> status ) ; break ; } spin_lock_irqsave ( & dev -> slock , flags ) ; dev -> isoc_ctl . isoc_copy ( dev , urb ) ; spin_unlock_irqrestore ( & dev -> slock , flags ) ; for ( i = 0 ; i < urb -> number_of_packets ; i ++ ) { urb -> iso_frame_desc [ i ] . status = 0 ; urb -> iso_frame_desc [ i ] . actual_length = 0 ; } urb -> status = 0 ; urb -> status = usb_submit_urb ( urb , GFP_ATOMIC ) ; if ( urb -> status ) { au0828_isocdbg ( "urb resubmit failed (error=%i)\n" , urb -> status ) ; } } 